/* Local-only commerce preview. No payment, backend order, or email is sent. */
(() => {
  const products = new Map((window.DESTINY_PRODUCTS || []).filter(p => Number.isFinite(p.price_aed_incl_vat)).map(p => [p.id, p]));
  const shipping = window.DESTINY_SHIPPING || {countries: []};
  const countries = new Map(shipping.countries.map(c => [c.code, c]));
  const cartKey = 'destiny-shop-demo-cart-v2';
  const oldCartKey = 'destiny-shop-demo-cart-v1';
  const shippingKey = 'destiny-shop-demo-shipping-v1';
  const ordersKey = 'destiny-shop-demo-orders-v1';
  const whatsappNumber = '918140840069';
  const copy = {
    en: {cart:n=>`Cart, ${n} ${n===1?'item':'items'}`, added:'Added to cart', stock:'Demo stock limit reached', empty:'Your cart is empty.',browse:'Browse products',remove:'Remove',quantity:'Quantity',each:'each, VAT included',size:'Size',finish:'Finish',other:'Shipping quote needed',unavailable:'Choose a listed country to continue the demo checkout.',status:'Demo status: not submitted to the business',ref:'Reference',method:'Shipping',total:'Estimated total incl. shipping',missing:'No demo order found on this device.',custom:'Custom furniture enquiry',name:'Name',email:'Email',country:'Delivery country',requirements:'Requirements'},
    ar: {cart:n=>`سلة التسوق، ${n} ${n===1?'قطعة':'قطع'}`,added:'أُضيف إلى السلة',stock:'وصلت إلى حد المخزون التجريبي',empty:'سلة التسوق فارغة.',browse:'تصفح المنتجات',remove:'إزالة',quantity:'الكمية',each:'للقطعة، شامل الضريبة',size:'المقاس',finish:'التشطيب',other:'يلزم عرض سعر للشحن',unavailable:'اختر بلداً مدرجاً لمتابعة إتمام الطلب التجريبي.',status:'حالة تجريبية: لم يُرسل إلى الشركة',ref:'رقم الطلب',method:'الشحن',total:'المجموع المقدر شامل الشحن',missing:'لم يُعثر على طلب تجريبي على هذا الجهاز.',custom:'استفسار عن أثاث حسب الطلب',name:'الاسم',email:'البريد الإلكتروني',country:'بلد التوصيل',requirements:'المتطلبات'}
  };
  const lang=()=>document.documentElement.lang==='ar'?'ar':'en';
  const money=n=>`AED ${new Intl.NumberFormat('en-AE',{minimumFractionDigits:Number.isInteger(n)?0:2,maximumFractionDigits:2}).format(n)}`;
  const option=(p,kind,code)=>p.demo_options[kind].find(item=>item.code===code)||p.demo_options[kind][0];
  const first=(p,kind)=>p.demo_options[kind][0].code;
  const keyFor=(id,size,finish)=>`${id}::${size}::${finish}`;
  const el=(tag,className,text)=>{const node=document.createElement(tag);if(className)node.className=className;if(text!==undefined)node.textContent=text;return node};
  let cart=[];
  try {
    const saved=JSON.parse(localStorage.getItem(cartKey)||'null');
    if(Array.isArray(saved)) cart=saved.filter(item=>{
      const p=products.get(item.id);
      return p&&Number.isInteger(item.quantity)&&item.quantity>0&&p.demo_options.size.some(x=>x.code===item.size)&&p.demo_options.finish.some(x=>x.code===item.finish);
    }).map(item=>({...item,quantity:Math.min(item.quantity,products.get(item.id).demo_stock)}));
    else {
      const legacy=JSON.parse(localStorage.getItem(oldCartKey)||'{}');
      for(const [id,quantity] of Object.entries(legacy)){
        const p=products.get(id);
        if(p&&Number.isInteger(quantity)&&quantity>0)cart.push({id,size:first(p,'size'),finish:first(p,'finish'),quantity:Math.min(quantity,p.demo_stock)});
      }
    }
  }catch{cart=[]}
  let destination='AE',method='standard';
  try {const saved=JSON.parse(localStorage.getItem(shippingKey)||'{}');if(countries.has(saved.destination)||saved.destination==='OTHER')destination=saved.destination;if(['standard','express'].includes(saved.method))method=saved.method}catch{}
  const count=()=>cart.reduce((sum,item)=>sum+item.quantity,0);
  const unitPrice=item=>{const p=products.get(item.id);return p.price_aed_incl_vat+option(p,'size',item.size).price_delta_aed+option(p,'finish',item.finish).price_delta_aed};
  const itemsTotal=()=>cart.reduce((sum,item)=>sum+unitPrice(item)*item.quantity,0);
  const shippingPrice=()=>count()&&countries.has(destination)?countries.get(destination)[`${method}_aed`]:destination==='OTHER'?null:0;
  const total=()=>shippingPrice()===null?null:itemsTotal()+shippingPrice();
  const stockUsed=id=>cart.filter(item=>item.id===id).reduce((sum,item)=>sum+item.quantity,0);
  function save(){try{localStorage.setItem(cartKey,JSON.stringify(cart))}catch{}render()}
  function saveShipping(){try{localStorage.setItem(shippingKey,JSON.stringify({destination,method}))}catch{}render()}
  function toast(message){let region=document.querySelector('.shop-toast');if(!region){region=el('div','shop-toast');region.setAttribute('role','status');region.setAttribute('aria-live','polite');document.body.append(region)}region.textContent=message;region.classList.add('show');clearTimeout(region.timer);region.timer=setTimeout(()=>region.classList.remove('show'),2800)}
  function add(id,size,finish,quantity){const p=products.get(id);if(!p)return;const available=p.demo_stock-stockUsed(id);if(available<quantity){toast(copy[lang()].stock);return}const key=keyFor(id,size,finish);let item=cart.find(i=>keyFor(i.id,i.size,i.finish)===key);if(item)item.quantity+=quantity;else cart.push({id,size,finish,quantity});save();toast(copy[lang()].added)}
  function details(item){const p=products.get(item.id),c=copy[lang()];return `${c.size}: ${option(p,'size',item.size).name[lang()]} · ${c.finish}: ${option(p,'finish',item.finish).name[lang()]}`}
  function renderCart(){const container=document.querySelector('[data-cart-items]');if(!container)return;container.replaceChildren();if(!cart.length){const empty=el('div','shop-cart-empty');empty.append(el('p','',copy[lang()].empty));const link=el('a','',copy[lang()].browse);link.href='./products.html';empty.append(link);container.append(empty)}
    for(const item of cart){const p=products.get(item.id),row=el('article','shop-cart-item'),imageLink=el('a','shop-cart-image');imageLink.href=`./product-${p.slug}.html`;const image=el('img');image.src=`./${p.image.replace('.webp','-480.webp')}`;image.alt=p.name[lang()];image.width=160;image.height=120;image.loading='lazy';imageLink.append(image);const info=el('div','shop-cart-item-info'),title=el('a','shop-cart-item-title',p.name[lang()]);title.href=imageLink.href;info.append(title,el('span','shop-cart-item-id',item.id),el('span','shop-cart-item-options',details(item)),el('span','shop-cart-item-price',`${money(unitPrice(item))} ${copy[lang()].each}`));const controls=el('div','shop-cart-controls'),label=el('label','',copy[lang()].quantity),input=el('input');input.type='number';input.min='1';input.max=String(p.demo_stock-stockUsed(item.id)+item.quantity);input.step='1';input.value=String(item.quantity);input.setAttribute('aria-label',`${copy[lang()].quantity}: ${p.name[lang()]}`);input.addEventListener('change',()=>{const next=Number(input.value),max=p.demo_stock-stockUsed(item.id)+item.quantity;if(!Number.isInteger(next)||next<1||next>max){input.value=String(item.quantity);toast(copy[lang()].stock);return}item.quantity=next;save()});label.append(input);const remove=el('button','shop-remove',copy[lang()].remove);remove.type='button';remove.setAttribute('aria-label',`${copy[lang()].remove}: ${p.name[lang()]}`);remove.addEventListener('click',()=>{cart=cart.filter(i=>i!==item);save()});controls.append(label,remove);info.append(controls);row.append(imageLink,info,el('strong','shop-cart-line-total',money(unitPrice(item)*item.quantity)));container.append(row)}
  }
  function renderSummary(){const countText=document.querySelector('[data-cart-count-text]');if(countText)countText.textContent=String(count());for(const node of document.querySelectorAll('[data-cart-vat]'))node.textContent=money(Math.round(itemsTotal()*5/105*100)/100);for(const node of document.querySelectorAll('[data-checkout-items]'))node.textContent=money(itemsTotal());for(const node of document.querySelectorAll('[data-cart-shipping]'))node.textContent=shippingPrice()===null?copy[lang()].other:money(shippingPrice());for(const node of document.querySelectorAll('[data-cart-total]'))node.textContent=total()===null?copy[lang()].other:money(total());for(const select of document.querySelectorAll('[data-shipping-country]'))select.value=destination;for(const select of document.querySelectorAll('[data-shipping-method]'))select.value=method;const checkout=document.querySelector('[data-checkout-link]');if(checkout){checkout.setAttribute('aria-disabled',String(!count()||total()===null));checkout.classList.toggle('is-disabled',!count()||total()===null)}const submit=document.querySelector('[data-checkout-form] button[type="submit"]');if(submit)submit.disabled=!count()||total()===null;const lines=document.querySelector('[data-checkout-lines]');if(lines){lines.replaceChildren();for(const item of cart){const p=products.get(item.id),line=el('p','shop-checkout-line');line.append(el('span','',`${p.name[lang()]} × ${item.quantity}`),el('strong','',money(unitPrice(item)*item.quantity)));lines.append(line)}if(!cart.length)lines.append(el('p','',copy[lang()].empty))}}
  function renderOrder(){const target=document.querySelector('[data-order-details]');if(!target)return;target.replaceChildren();const ref=new URLSearchParams(location.search).get('ref');let orders={};try{orders=JSON.parse(localStorage.getItem(ordersKey)||'{}')}catch{}const order=ref&&orders[ref];if(!order){target.append(el('p','',copy[lang()].missing));return}const c=copy[lang()];target.append(el('h2','',`${c.ref}: ${ref}`),el('p','shop-order-status',c.status));const list=el('ul');for(const item of order.items){const p=products.get(item.id);if(p)list.append(el('li','',`${p.name[lang()]} × ${item.quantity} — ${money(item.unitPrice*item.quantity)}`))}target.append(list,el('p','',`${c.country}: ${countries.get(order.country)?.name[lang()]||order.country}`),el('p','',`${c.method}: ${order.method==='express'?(lang()==='ar'?'سريع':'Express'):(lang()==='ar'?'عادي':'Standard')}`),el('strong','shop-order-total',`${c.total}: ${money(order.total)}`))}
  function renderProduct(){const price=document.querySelector('[data-product-price]');if(!price)return;const id=document.querySelector('.shop-detail-add')?.dataset.addToCart,p=products.get(id);if(!p)return;const size=document.querySelector('[data-product-option="size"]').value,finish=document.querySelector('[data-product-option="finish"]').value,quantity=Math.max(1,Number(document.querySelector('[data-product-quantity]').value)||1);price.textContent=money(unitPrice({id,size,finish})*quantity)}
  function render(){for(const node of document.querySelectorAll('[data-cart-count]'))node.textContent=String(count());for(const node of document.querySelectorAll('[data-cart-label]'))node.setAttribute('aria-label',copy[lang()].cart(count()));for(const node of document.querySelectorAll('[data-shop-en][data-shop-ar]'))node.textContent=node.dataset[lang()==='ar'?'shopAr':'shopEn'];renderCart();renderSummary();renderOrder();renderProduct()}
  document.addEventListener('click',event=>{const button=event.target.closest('[data-add-to-cart]');if(button){const id=button.dataset.addToCart,p=products.get(id);if(!p)return;const scope=button.closest('.catalog-detail-head');const size=scope?.querySelector('[data-product-option="size"]')?.value||first(p,'size'),finish=scope?.querySelector('[data-product-option="finish"]')?.value||first(p,'finish');const quantity=scope?Number(scope.querySelector('[data-product-quantity]').value):1;if(!Number.isInteger(quantity)||quantity<1||quantity>99){toast(copy[lang()].stock);return}add(id,size,finish,quantity)}});
  for(const select of document.querySelectorAll('[data-shipping-country]'))select.addEventListener('change',()=>{destination=select.value;saveShipping()});
  for(const select of document.querySelectorAll('[data-shipping-method]'))select.addEventListener('change',()=>{method=select.value;saveShipping()});
  document.querySelector('[data-checkout-link]')?.addEventListener('click',event=>{if(!count()||total()===null){event.preventDefault();toast(copy[lang()].unavailable)}});
  document.querySelectorAll('[data-product-option],[data-product-quantity]').forEach(input=>input.addEventListener('change',renderProduct));
  document.querySelector('[data-checkout-form]')?.addEventListener('submit',event=>{event.preventDefault();if(!count()||total()===null){toast(copy[lang()].unavailable);return}const form=event.currentTarget;if(!form.reportValidity())return;const ref=`DEMO-${Date.now().toString(36).toUpperCase()}-${Math.random().toString(36).slice(2,6).toUpperCase()}`;let orders={};try{orders=JSON.parse(localStorage.getItem(ordersKey)||'{}')}catch{}orders[ref]={country:destination,method,payment:form.elements.payment.value,items:cart.map(item=>({...item,unitPrice:unitPrice(item)})),itemsTotal:itemsTotal(),shipping:shippingPrice(),total:total(),createdAt:new Date().toISOString(),status:'demo-unsubmitted'};try{localStorage.setItem(ordersKey,JSON.stringify(orders))}catch{toast('Unable to save demo order on this device.');return}cart=[];save();location.href=`./order.html?ref=${encodeURIComponent(ref)}`});
  document.querySelector('[data-custom-enquiry]')?.addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const c=copy[lang()],data=new FormData(form),name=form.dataset[lang()==='ar'?'productNameAr':'productNameEn'];const message=[`${c.custom}: ${name} (${form.dataset.productId})`,`${c.name}: ${data.get('name')}`,`${c.email}: ${data.get('email')}`,`${c.country}: ${data.get('country')}`,`${c.requirements}: ${data.get('details')}`].join('\n');window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`,'_blank','noopener,noreferrer')});
  document.querySelectorAll('[data-gallery-image]').forEach(button=>button.addEventListener('click',()=>{const image=document.querySelector('.catalog-detail-image>img');image.removeAttribute('srcset');image.src=button.dataset.galleryImage;image.alt=button.dataset[lang()==='ar'?'galleryAltAr':'galleryAltEn']}));
  new MutationObserver(render).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
  render();
})();
